import { Google } from "arctic";

function getGoogleClient() {
  const clientId = process.env.GOOGLE_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
  const redirectUri =
    process.env.GOOGLE_REDIRECT_URI ||
    "http://localhost:5173/auth/google/callback";

  if (!clientId || !clientSecret) {
    throw new Error(
      "Missing GOOGLE_CLIENT_ID or GOOGLE_CLIENT_SECRET environment variables"
    );
  }

  return new Google(clientId, clientSecret, redirectUri);
}

export function createGoogleAuthUrl(): {
  url: URL;
  state: string;
  codeVerifier: string;
} {
  const google = getGoogleClient();
  const state = crypto.randomUUID();
  const codeVerifier = crypto.randomUUID();
  const scopes = ["openid", "profile", "email"];

  const url = google.createAuthorizationURL(state, codeVerifier, scopes);

  return { url, state, codeVerifier };
}

export async function validateGoogleCallback({
  code,
  codeVerifier,
}: {
  code: string;
  codeVerifier: string;
}) {
  const google = getGoogleClient();
  const tokens = await google.validateAuthorizationCode(code, codeVerifier);
  return tokens;
}

export interface GoogleUserInfo {
  sub: string; // Google's unique user ID
  name: string;
  email: string;
  picture?: string;
}

export async function getGoogleUserInfo(
  accessToken: string
): Promise<GoogleUserInfo> {
  const response = await fetch(
    "https://openidconnect.googleapis.com/v1/userinfo",
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    }
  );

  if (!response.ok) {
    throw new Error("Failed to fetch user info from Google");
  }

  return response.json();
}

import { redirect } from "react-router";
import { Effect, Option } from "effect";
import { UserRepository, type User } from "@ai-interviewer/shared";
import {
  validateGoogleCallback,
  getGoogleUserInfo,
} from "~/auth/google.server";
import {
  createSession,
  createSessionCookie,
  getOAuthStateFromCookies,
  clearOAuthStateCookies,
} from "~/auth/session.server";
import { AllRepositoriesLive } from "~/db/repositories";
import type { Route } from "./+types/auth.google.callback";

export async function loader({ request }: Route.LoaderArgs) {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  const state = url.searchParams.get("state");

  if (!code || !state) {
    return redirect("/auth/error?error=missing_params");
  }

  const cookieHeader = request.headers.get("Cookie");
  const { state: storedState, codeVerifier } =
    getOAuthStateFromCookies(cookieHeader);

  if (!storedState || !codeVerifier || state !== storedState) {
    return redirect("/auth/error?error=invalid_state");
  }

  try {
    // Validate OAuth callback and get tokens
    const tokens = await validateGoogleCallback({ code, codeVerifier });

    // Get user info from Google
    const googleUser = await getGoogleUserInfo(tokens.accessToken());

    // Find or create user in database
    const findOrCreateUser: Effect.Effect<
      User,
      never,
      typeof UserRepository.Service
    > = Effect.gen(function* () {
      const userRepo = yield* UserRepository;
      const existingUser = yield* userRepo.findByGoogleId(googleUser.sub);

      if (Option.isSome(existingUser)) {
        return existingUser.value;
      }

      // Create new user
      return yield* userRepo.create({
        googleId: googleUser.sub,
        email: googleUser.email,
        name: googleUser.name,
        avatarUrl: googleUser.picture ?? null,
      });
    });

    const user = await Effect.runPromise(
      Effect.provide(findOrCreateUser, AllRepositoriesLive)
    );

    // Create session JWT
    const sessionToken = await createSession({
      userId: user.id,
      email: user.email,
      name: user.name,
    });

    // Clear OAuth state cookies and set session cookie
    const clearCookies = clearOAuthStateCookies();
    const sessionCookie = createSessionCookie(sessionToken);

    return redirect("/", {
      headers: [
        ...clearCookies.map((c): [string, string] => ["Set-Cookie", c]),
        ["Set-Cookie", sessionCookie],
      ],
    });
  } catch (error) {
    console.error("OAuth callback error:", error);
    return redirect("/auth/error?error=oauth_failed");
  }
}

import * as jose from "jose";

const JWT_SECRET =
  process.env.JWT_SECRET || "development-secret-change-in-production";
const JWT_ISSUER = "ai-interviewer";
const JWT_AUDIENCE = "ai-interviewer-users";
const COOKIE_NAME = "session";
const COOKIE_MAX_AGE = 60 * 60 * 24 * 30; // 30 days

interface SessionPayload {
  userId: string;
  email: string;
  name: string;
}

export async function createSession(payload: SessionPayload): Promise<string> {
  const secret = new TextEncoder().encode(JWT_SECRET);

  const jwt = await new jose.SignJWT({
    userId: payload.userId,
    email: payload.email,
    name: payload.name,
  })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setIssuer(JWT_ISSUER)
    .setAudience(JWT_AUDIENCE)
    .setExpirationTime("30d")
    .sign(secret);

  return jwt;
}

export async function verifySession(
  token: string
): Promise<SessionPayload | null> {
  try {
    const secret = new TextEncoder().encode(JWT_SECRET);
    const { payload } = await jose.jwtVerify(token, secret, {
      issuer: JWT_ISSUER,
      audience: JWT_AUDIENCE,
    });

    return {
      userId: payload.userId as string,
      email: payload.email as string,
      name: payload.name as string,
    };
  } catch {
    return null;
  }
}

export function createSessionCookie(token: string): string {
  const secure = process.env.NODE_ENV === "production";
  const sameSite = secure ? "Lax" : "Lax";

  return `${COOKIE_NAME}=${token}; Path=/; HttpOnly; SameSite=${sameSite}; Max-Age=${COOKIE_MAX_AGE}${secure ? "; Secure" : ""}`;
}

export function createLogoutCookie(): string {
  return `${COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`;
}

export function getSessionFromCookie(
  cookieHeader: string | null
): string | null {
  if (!cookieHeader) return null;

  const cookies = cookieHeader.split(";").map((c) => c.trim());
  const sessionCookie = cookies.find((c) => c.startsWith(`${COOKIE_NAME}=`));

  if (!sessionCookie) return null;

  return sessionCookie.slice(COOKIE_NAME.length + 1);
}

export async function getSessionFromRequest(
  request: Request
): Promise<SessionPayload | null> {
  const cookieHeader = request.headers.get("Cookie");
  const token = getSessionFromCookie(cookieHeader);

  if (!token) return null;

  return verifySession(token);
}

// OAuth state cookie helpers
const STATE_COOKIE_NAME = "oauth_state";
const VERIFIER_COOKIE_NAME = "oauth_verifier";
const STATE_COOKIE_MAX_AGE = 60 * 10; // 10 minutes

export function createOAuthStateCookies({
  state,
  codeVerifier,
}: {
  state: string;
  codeVerifier: string;
}): string[] {
  const secure = process.env.NODE_ENV === "production";
  return [
    `${STATE_COOKIE_NAME}=${state}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${STATE_COOKIE_MAX_AGE}${secure ? "; Secure" : ""}`,
    `${VERIFIER_COOKIE_NAME}=${codeVerifier}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${STATE_COOKIE_MAX_AGE}${secure ? "; Secure" : ""}`,
  ];
}

export function getOAuthStateFromCookies(cookieHeader: string | null): {
  state: string | null;
  codeVerifier: string | null;
} {
  if (!cookieHeader) return { state: null, codeVerifier: null };

  const cookies = cookieHeader.split(";").map((c) => c.trim());

  const stateCookie = cookies.find((c) =>
    c.startsWith(`${STATE_COOKIE_NAME}=`)
  );
  const verifierCookie = cookies.find((c) =>
    c.startsWith(`${VERIFIER_COOKIE_NAME}=`)
  );

  return {
    state: stateCookie ? stateCookie.slice(STATE_COOKIE_NAME.length + 1) : null,
    codeVerifier: verifierCookie
      ? verifierCookie.slice(VERIFIER_COOKIE_NAME.length + 1)
      : null,
  };
}

export function clearOAuthStateCookies(): string[] {
  return [
    `${STATE_COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`,
    `${VERIFIER_COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`,
  ];
}

import { useSearchParams } from "react-router";

export function meta() {
  return [{ title: "Authentication Error - AI Interviewer" }];
}

export default function AuthError() {
  const [searchParams] = useSearchParams();
  const errorParam = searchParams.get("error");

  const errorMessages: Record<string, string> = {
    missing_params: "Missing required authentication parameters.",
    invalid_state: "Invalid authentication state. Please try again.",
    oauth_failed: "Authentication failed. Please try again.",
  };

  const message = errorParam
    ? errorMessages[errorParam] || "An unknown error occurred."
    : "An error occurred during authentication.";

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", padding: "2rem" }}>
      <h1>Authentication Error</h1>
      <p>{message}</p>
      <p>
        <a href="/auth/google">Try again</a> | <a href="/">Go home</a>
      </p>
    </div>
  );
}

import { redirect } from "react-router";
import { getSessionFromRequest } from "./session.server";

export interface AuthenticatedUser {
  userId: string;
  email: string;
  name: string;
}

/**
 * Require authentication for a route.
 * Throws a redirect to the login page if not authenticated.
 */
export async function requireAuth(
  request: Request
): Promise<AuthenticatedUser> {
  const session = await getSessionFromRequest(request);

  if (!session) {
    throw redirect("/auth/google");
  }

  return session;
}

/**
 * Get the current user if authenticated, or null if not.
 * Does not redirect - useful for pages that show different content based on auth status.
 */
export async function getOptionalUser(
  request: Request
): Promise<AuthenticatedUser | null> {
  return getSessionFromRequest(request);
}

import { Effect, Exit, Cause } from "effect";
import {
  TakeService,
  TakeNotFoundError,
  InterviewNotFoundError,
  UnauthorizedError,
  type TakeStage,
} from "@ai-interviewer/shared";
import { requireAuth } from "~/auth/require-auth.server";
import { AppLayer } from "~/db/repositories";
import type { Route } from "./+types/api.takes.$id";

/**
 * GET /api/takes/:id - Get a single take by ID
 */
export async function loader({ request, params }: Route.LoaderArgs) {
  const user = await requireAuth(request);
  const { id } = params;

  const program = Effect.gen(function* () {
    const service = yield* TakeService;
    return yield* service.getById({ id, userId: user.userId });
  });

  const exit = await Effect.runPromiseExit(Effect.provide(program, AppLayer));

  if (Exit.isFailure(exit)) {
    const cause = exit.cause;
    if (Cause.isFailType(cause)) {
      const error = cause.error;
      if (error instanceof TakeNotFoundError) {
        return Response.json({ error: "Take not found" }, { status: 404 });
      }
      if (error instanceof InterviewNotFoundError) {
        return Response.json({ error: "Interview not found" }, { status: 404 });
      }
      if (error instanceof UnauthorizedError) {
        return Response.json({ error: "Unauthorized" }, { status: 403 });
      }
    }
    return Response.json({ error: "Failed to fetch take" }, { status: 500 });
  }

  return Response.json({ take: exit.value });
}

/**
 * PATCH /api/takes/:id - Update take stage (pre-interview -> interview)
 */
export async function action({ request, params }: Route.ActionArgs) {
  const user = await requireAuth(request);
  const { id } = params;

  if (request.method === "PATCH") {
    let body: { stage?: TakeStage };
    try {
      body = await request.json();
    } catch {
      return Response.json({ error: "Invalid JSON body" }, { status: 400 });
    }

    if (!body.stage) {
      return Response.json({ error: "Stage is required" }, { status: 400 });
    }

    if (body.stage !== "pre-interview" && body.stage !== "interview") {
      return Response.json(
        { error: "Stage must be 'pre-interview' or 'interview'" },
        { status: 400 }
      );
    }

    const program = Effect.gen(function* () {
      const service = yield* TakeService;
      return yield* service.updateStage({
        id,
        userId: user.userId,
        stage: body.stage!,
      });
    });

    const exit = await Effect.runPromiseExit(Effect.provide(program, AppLayer));

    if (Exit.isFailure(exit)) {
      const cause = exit.cause;
      if (Cause.isFailType(cause)) {
        const error = cause.error;
        if (error instanceof TakeNotFoundError) {
          return Response.json({ error: "Take not found" }, { status: 404 });
        }
        if (error instanceof InterviewNotFoundError) {
          return Response.json(
            { error: "Interview not found" },
            { status: 404 }
          );
        }
        if (error instanceof UnauthorizedError) {
          return Response.json({ error: "Unauthorized" }, { status: 403 });
        }
      }
      return Response.json({ error: "Failed to update take" }, { status: 500 });
    }

    return Response.json({ take: exit.value });
  }

  return Response.json({ error: "Method not allowed" }, { status: 405 });
}

import { Effect, Exit } from "effect";
